"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";

type Currency = { id: string; code: string };
type Provider = { id: string; name: string; websiteUrl?: string | null };
type Account = { id: string; name: string; accountType: string; provider: Provider; currency: Currency; accountNumberMasked?: string | null; note?: string | null; isActive?: boolean; cashAccount?: { id: string; balance: string | number } | null };
type Asset = { id: string; symbol?: string | null; name: string; assetType: string; unitName: string; currency: Currency };
type Holding = { id: string; quantity: string | number; costBasis: string | number; currentPrice?: string | number | null; marketValue: string | number; gain: string | number; returnPct: string | number; asset: Asset; account: Account };
type Cash = { id: string; balance: string | number; account: Account };
type Sale = { id: string; date: string; quantity: string | number; price: string | number; proceeds: string | number; realized: string | number };
type LotRow = { id: string; lotId: string; transactionDate: string; asset: Asset; quantity: string | number; soldQuantity: string | number; remainingQuantity: string | number; unitPrice: string | number; totalCost: string | number; minimumSellPrice: string | number; currentPrice: string | number | null; priceAsOf: string | null; currentValue: string | number; unrealizedGainLoss: string | number; sales: Sale[] };
type Ledger = { account: Account; rows: LotRow[]; summary: { openLots: number; openQuantity: string | number; realizedGainLoss: string | number } };
type Overview = { currencies: Currency[]; providers: Provider[]; accounts: Account[]; assets: Asset[]; holdings: Holding[]; cashAccounts: Cash[]; summary: { totalValue: string | number; totalCash: string | number; totalInvestmentValue: string | number; unrealized: string | number; returnPct: string | number } };
type RdnHistoryRow = { id: string; date: string; description: string; debit: string | number; credit: string | number; balance: string | number; movementType: string };
type AssetSummary = { asset: Asset; quantity: number; cost: number; avgCost: number; currentPrice: number | null; marketValue: number; sellFee: number; netValue: number; pnl: number; minSell: number; rows: LotRow[] };
type AccountForm = { providerName: string; websiteUrl: string; rdnBankName: string; rdnAccountNumber: string; buyFeePct: string; sellFeePct: string; currencyId: string };
type Trade = { type: "BUY" | "SELL"; assetId: string; assetQuery: string; quantity: string; unitPrice: string; tax: string; other: string; date: string; sourceLotId: string; fundingCashAccountId: string };

const input = "w-full rounded-xl border border-white/10 bg-[#080f17] px-3 py-2.5 text-sm text-white outline-none placeholder:text-slate-600";
const select = `${input} text-slate-300`;
const card = "rounded-2xl border border-white/10 bg-[#0d151e] p-5";
const today = () => new Date().toISOString().slice(0, 10);
const nf = (value: string | number | null | undefined, digits = 2) => { const x = Number(value ?? 0); return Number.isFinite(x) ? new Intl.NumberFormat("id-ID", { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(x) : "0"; };
const cp = (code: string) => ({ IDR: "Rp", USD: "US$", SGD: "S$", MYR: "RM", JPY: "¥", EUR: "€", GBP: "£" } as Record<string, string>)[code] ?? code;
const money = (value: string | number | null | undefined, code = "IDR") => `${cp(code)}${nf(value)}`;
const feeInfo = (a: Account) => { try { const p = a.note ? JSON.parse(a.note) as Record<string, unknown> : {}; return { buyFeePct: Number(p.buyFeePct ?? 0) || 0, sellFeePct: Number(p.sellFeePct ?? 0) || 0, rdnBankName: String(p.rdnBankName ?? ""), rdnAccountNumber: String(p.rdnAccountNumber ?? "") }; } catch { return { buyFeePct: 0, sellFeePct: 0, rdnBankName: "", rdnAccountNumber: "" }; } };
const assetLabel = (a: Asset) => a.symbol ? `${a.symbol} · ${a.name}` : a.name;
const unitsPerLot = (a?: Asset) => a?.assetType === "STOCK" ? 100 : 1;

async function getOverview(): Promise<Overview> { const r = await fetch("/api/investments", { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load investments."); return j; }
async function postV2(body: Record<string, unknown>) { const r = await fetch("/api/investments/v2", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Investment operation failed."); return j; }
async function postV4(body: Record<string, unknown>) { const r = await fetch("/api/investments/v4", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Investment operation failed."); return j; }

function AssetPicker({ assets, value, selectedId, onChange, onSelect }: { assets: Asset[]; value: string; selectedId: string; onChange: (v: string) => void; onSelect: (a: Asset) => void }) {
  const [open, setOpen] = useState(false);
  const q = value.trim().toLowerCase();
  const filtered = useMemo(() => assets.filter(a => !q || assetLabel(a).toLowerCase().includes(q) || String(a.symbol ?? "").toLowerCase() === q || a.name.toLowerCase().includes(q)).slice(0, 12), [assets, q]);
  return <div className="relative">
    <input className={`${input} ${selectedId ? "border-emerald-400/40" : ""}`} placeholder="Asset / Stock (type to search)" value={value} autoComplete="off" onFocus={() => setOpen(true)} onChange={e => { const next = e.target.value; onChange(next); setOpen(true); const exact = assets.find(a => String(a.symbol ?? "").toLowerCase() === next.trim().toLowerCase() || assetLabel(a).toLowerCase() === next.trim().toLowerCase()); if (exact) onSelect(exact); }} />
    {open && <div className="absolute z-[80] mt-1 max-h-64 w-full overflow-y-auto rounded-xl border border-white/10 bg-[#0b121a] p-1 shadow-2xl">
      {filtered.length ? filtered.map(a => <button key={a.id} type="button" onMouseDown={e => e.preventDefault()} onClick={() => { onSelect(a); setOpen(false); }} className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left hover:bg-white/[.05]"><span><span className="block text-sm font-semibold text-white">{a.symbol || a.name}</span><span className="block text-[10px] text-slate-500">{a.name}</span></span><span className="text-[9px] uppercase text-slate-600">{a.assetType}</span></button>) : <div className="px-3 py-3 text-xs text-slate-600">Asset baru akan dibuat otomatis untuk BUY.</div>}
      {q && !filtered.some(a => String(a.symbol ?? "").toLowerCase() === q) && <div className="px-3 py-2 text-[10px] text-emerald-300">Kode “{value.trim().toUpperCase()}” akan dibuat saat BUY disimpan.</div>}
    </div>}
  </div>;
}

function AccountModal({ open, editing, form, currencies, onClose, onChange, onSubmit, busy }: { open: boolean; editing: Account | null; form: AccountForm; currencies: Currency[]; onClose: () => void; onChange: (f: AccountForm) => void; onSubmit: (e: FormEvent) => void; busy: boolean }) {
  if (!open) return null;
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><form onSubmit={onSubmit} className="w-full max-w-2xl rounded-3xl border border-white/10 bg-[#0b121a] p-6 shadow-2xl"><div className="mb-6 flex items-start justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-emerald-400">Investments</p><h2 className="mt-1 text-2xl font-bold text-white">{editing ? "Edit RDN Account" : "Add RDN Account"}</h2><p className="mt-1 text-xs text-slate-500">Buat akun sekali. Setelah itu account akan selalu tersedia di tab Accounts.</p></div><button type="button" onClick={onClose} className="text-2xl text-slate-500 hover:text-white">×</button></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-500">Investment account / broker<input className={`${input} mt-2`} value={form.providerName} onChange={e => onChange({ ...form, providerName: e.target.value })} placeholder="contoh: IndoPremier" /></label><label className="text-xs text-slate-500">Website<input className={`${input} mt-2`} value={form.websiteUrl} onChange={e => onChange({ ...form, websiteUrl: e.target.value })} placeholder="https://..." /></label><label className="text-xs text-slate-500">RDN Bank<input className={`${input} mt-2`} value={form.rdnBankName} onChange={e => onChange({ ...form, rdnBankName: e.target.value })} placeholder="contoh: BCA" /></label><label className="text-xs text-slate-500">RDN Account Number<input className={`${input} mt-2`} value={form.rdnAccountNumber} onChange={e => onChange({ ...form, rdnAccountNumber: e.target.value })} placeholder="Nomor RDN" /></label><label className="text-xs text-slate-500">Currency<select className={`${select} mt-2`} value={form.currencyId} onChange={e => onChange({ ...form, currencyId: e.target.value })}>{currencies.map(c => <option key={c.id} value={c.id}>{c.code}</option>)}</select></label><div /><label className="text-xs text-slate-500">Buy fee %<input className={`${input} mt-2`} type="number" min="0" step="0.001" value={form.buyFeePct} onChange={e => onChange({ ...form, buyFeePct: e.target.value })} /></label><label className="text-xs text-slate-500">Sell fee %<input className={`${input} mt-2`} type="number" min="0" step="0.001" value={form.sellFeePct} onChange={e => onChange({ ...form, sellFeePct: e.target.value })} /></label></div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-4 py-2.5 text-sm text-slate-300">Cancel</button><button type="submit" disabled={busy} className="rounded-xl bg-emerald-400 px-5 py-2.5 text-sm font-bold text-[#07110b] disabled:opacity-50">{busy ? "Saving…" : editing ? "Save changes" : "Create account"}</button></div></form></div>;
}

function TradeModal({ open, trade, assets, account, ledger, compatibleCashId, onClose, onChange, onSubmit, busy }: { open: boolean; trade: Trade; assets: Asset[]; account: Account; ledger: Ledger | null; compatibleCashId: string; onClose: () => void; onChange: (t: Trade) => void; onSubmit: (e: FormEvent) => void; busy: boolean }) {
  const selectedAsset = assets.find(a => a.id === trade.assetId) ?? assets.find(a => assetLabel(a).toLowerCase() === trade.assetQuery.trim().toLowerCase());
  const lots = (ledger?.rows ?? []).filter(r => r.asset.id === trade.assetId && Number(r.remainingQuantity) > 0);
  const feePct = trade.type === "BUY" ? feeInfo(account).buyFeePct : feeInfo(account).sellFeePct;
  const units = unitsPerLot(selectedAsset);
  const gross = Number(trade.quantity || 0) * units * Number(trade.unitPrice || 0);
  const fee = gross * feePct / 100;
  const cash = trade.type === "BUY" ? gross + fee + Number(trade.tax || 0) + Number(trade.other || 0) : gross - fee - Number(trade.tax || 0) - Number(trade.other || 0);
  const canSubmit = !!trade.assetQuery.trim() && Number(trade.quantity) > 0 && Number(trade.unitPrice) > 0 && !!trade.fundingCashAccountId && (trade.type === "BUY" || !!trade.sourceLotId);
  if (!open) return null;
  return <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><form onSubmit={onSubmit} className="w-full max-w-4xl rounded-3xl border border-white/10 bg-[#0b121a] p-6 shadow-2xl"><div className="mb-5 flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-[.18em] text-emerald-400">{account.provider.name}</p><h2 className="mt-1 text-2xl font-bold text-white">New {trade.type === "BUY" ? "Buy" : "Sell"} Transaction</h2></div><button type="button" onClick={onClose} className="text-2xl text-slate-500 hover:text-white">×</button></div><div className="mb-5 grid grid-cols-2 rounded-2xl border border-white/10 bg-[#080f17] p-1"><button type="button" onClick={() => onChange({ ...trade, type: "BUY", sourceLotId: "" })} className={`rounded-xl py-3 text-lg font-bold ${trade.type === "BUY" ? "bg-emerald-400 text-[#07110b]" : "text-slate-500"}`}>BUY</button><button type="button" onClick={() => onChange({ ...trade, type: "SELL", sourceLotId: "" })} className={`rounded-xl py-3 text-lg font-bold ${trade.type === "SELL" ? "bg-emerald-400 text-[#07110b]" : "text-slate-500"}`}>SELL</button></div><div className="grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-500">Asset / Stock<AssetPicker assets={assets} value={trade.assetQuery} selectedId={trade.assetId} onChange={v => onChange({ ...trade, assetQuery: v, assetId: assets.find(a => assetLabel(a).toLowerCase() === v.trim().toLowerCase() || String(a.symbol ?? "").toLowerCase() === v.trim().toLowerCase())?.id ?? "" })} onSelect={a => onChange({ ...trade, assetId: a.id, assetQuery: assetLabel(a), sourceLotId: trade.type === "SELL" ? "" : trade.sourceLotId })} /></label><label className="text-xs text-slate-500">Date<input className={`${input} mt-2`} type="date" value={trade.date} onChange={e => onChange({ ...trade, date: e.target.value })} /></label><label className="text-xs text-slate-500">Quantity {selectedAsset?.assetType === "STOCK" ? "(lots)" : `(${selectedAsset?.unitName || "units"})`}<input className={`${input} mt-2`} type="number" min="0.0001" step="0.0001" value={trade.quantity} onChange={e => onChange({ ...trade, quantity: e.target.value })} placeholder="1" /></label><label className="text-xs text-slate-500">Price / unit<input className={`${input} mt-2`} type="number" min="0.01" step="0.01" value={trade.unitPrice} onChange={e => onChange({ ...trade, unitPrice: e.target.value })} placeholder="3150" /></label></div>{trade.type === "SELL" && selectedAsset && <label className="mt-4 block text-xs text-slate-500">Purchase lot to sell<select className={`${select} mt-2`} value={trade.sourceLotId} onChange={e => onChange({ ...trade, sourceLotId: e.target.value })}><option value="">Select remaining lot</option>{lots.map(r => <option key={r.lotId} value={r.lotId}>{new Date(r.transactionDate).toLocaleDateString("id-ID")} · {nf(Number(r.remainingQuantity) / units, selectedAsset.assetType === "STOCK" ? 0 : 2)} {selectedAsset.assetType === "STOCK" ? "lot" : selectedAsset.unitName} · cost {money(Number(r.totalCost) * (Number(r.remainingQuantity) / Math.max(Number(r.quantity), 1)), account.currency.code)}</option>)}</select></label>}<div className="mt-4 grid gap-3 md:grid-cols-3"><div className="rounded-2xl border border-white/10 bg-white/[.02] p-4"><p className="text-[10px] uppercase tracking-widest text-slate-600">Auto fee · {feePct.toFixed(3)}%</p><p className="mt-2 text-lg font-bold text-emerald-300">{money(fee, account.currency.code)}</p></div><div className="rounded-2xl border border-white/10 bg-white/[.02] p-4"><p className="text-[10px] uppercase tracking-widest text-slate-600">{trade.type === "BUY" ? "Cash required" : "Net proceeds"}</p><p className="mt-2 text-lg font-bold text-white">{money(cash, account.currency.code)}</p></div><div className="rounded-2xl border border-white/10 bg-white/[.02] p-4"><p className="text-[10px] uppercase tracking-widest text-slate-600">Settlement RDN</p><select className="mt-2 w-full bg-transparent text-sm text-white outline-none" value={trade.fundingCashAccountId || compatibleCashId} onChange={e => onChange({ ...trade, fundingCashAccountId: e.target.value })}><option className="bg-[#0b121a]" value="">Select RDN</option>{account.cashAccount?.id && <option className="bg-[#0b121a]" value={account.cashAccount.id}>{account.provider.name} · RDN · {money(account.cashAccount.balance, account.currency.code)}</option>}</select></div></div><details className="mt-4 rounded-2xl border border-white/10 p-4"><summary className="cursor-pointer text-sm font-semibold text-slate-300">Tax / Other</summary><div className="mt-4 grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-500">Tax<input className={`${input} mt-2`} type="number" min="0" step="0.01" value={trade.tax} onChange={e => onChange({ ...trade, tax: e.target.value })} /></label><label className="text-xs text-slate-500">Other charges<input className={`${input} mt-2`} type="number" min="0" step="0.01" value={trade.other} onChange={e => onChange({ ...trade, other: e.target.value })} /></label></div></details><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-5 py-3 text-sm text-slate-300">Cancel</button><button type="submit" disabled={busy || !canSubmit} className="rounded-xl bg-emerald-400 px-6 py-3 text-sm font-bold text-[#07110b] disabled:cursor-not-allowed disabled:opacity-40">{busy ? "Saving…" : "Save transaction"}</button></div></form></div>;
}

function SellAllModal({ open, asset, preview, price, currency, onClose, onPrice, onConfirm, busy }: { open: boolean; asset: AssetSummary | undefined; preview: { totalGross: number; totalFee: number; totalNet: number; totalCost: number; pnl: number; rows: Array<{ row: LotRow; qty: number; gross: number; sellFee: number; net: number; cost: number; pnl: number }> } | null; price: string; currency: string; onClose: () => void; onPrice: (v: string) => void; onConfirm: () => void; busy: boolean }) {
  if (!open || !asset) return null;
  return <div className="fixed inset-0 z-[105] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"><div className="w-full max-w-4xl rounded-3xl border border-white/10 bg-[#0b121a] p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-[.18em] text-emerald-400">Sell All</p><h2 className="mt-1 text-2xl font-bold text-white">{asset.asset.symbol || asset.asset.name}</h2><p className="mt-1 text-xs text-slate-500">Set one sell price. OKANE will create SELL details for every remaining purchase lot.</p></div><button type="button" onClick={onClose} className="text-2xl text-slate-500 hover:text-white">×</button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><div><label className="text-xs text-slate-500">Sell price / share</label><input className={`${input} mt-2`} type="number" min="0.01" step="0.01" value={price} onChange={e => onPrice(e.target.value)} placeholder={asset.currentPrice ? String(asset.currentPrice) : "Price"} /></div><div className="rounded-2xl border border-emerald-400/20 bg-emerald-400/[.04] p-4"><p className="text-[10px] uppercase tracking-widest text-slate-500">Break-even guide</p><p className="mt-1 text-lg font-bold text-emerald-300">{money(asset.minSell, currency)}</p><p className="mt-1 text-[10px] text-slate-500">Minimum price to target P/L ≈ 0 after sell fee.</p></div></div>{preview && <><div className="mt-5 grid gap-3 md:grid-cols-4"><div className="rounded-xl border border-white/10 p-3"><p className="text-[10px] text-slate-600">Gross</p><p className="mt-1 font-bold text-white">{money(preview.totalGross, currency)}</p></div><div className="rounded-xl border border-white/10 p-3"><p className="text-[10px] text-slate-600">Sell fee</p><p className="mt-1 font-bold text-red-300">{money(preview.totalFee, currency)}</p></div><div className="rounded-xl border border-white/10 p-3"><p className="text-[10px] text-slate-600">Net proceeds</p><p className="mt-1 font-bold text-white">{money(preview.totalNet, currency)}</p></div><div className="rounded-xl border border-white/10 p-3"><p className="text-[10px] text-slate-600">P/L</p><p className={`mt-1 font-bold ${preview.pnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{money(preview.pnl, currency)}</p></div></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-3 py-2">Purchase date</th><th>Remaining</th><th>Cost</th><th>Net proceeds</th><th className="text-right">P/L</th></tr></thead><tbody className="divide-y divide-white/5">{preview.rows.map(x => <tr key={x.row.id}><td className="px-3 py-3 text-slate-400">{new Date(x.row.transactionDate).toLocaleDateString("id-ID")}</td><td>{nf(x.qty / unitsPerLot(x.row.asset), x.row.asset.assetType === "STOCK" ? 0 : 2)}</td><td>{money(x.cost, currency)}</td><td>{money(x.net, currency)}</td><td className={`text-right ${x.pnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{money(x.pnl, currency)}</td></tr>)}</tbody></table></div></>}
<div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-white/10 px-5 py-3 text-sm text-slate-300">Cancel</button><button type="button" disabled={busy || !price || Number(price) <= 0} onClick={onConfirm} className="rounded-xl bg-emerald-400 px-6 py-3 text-sm font-bold text-[#07110b] disabled:opacity-40">{busy ? "Processing…" : "Confirm Sell All"}</button></div></div></div>;
}

function RdnHistory({ rows, currency }: { rows: RdnHistoryRow[]; currency: string }) {
  return <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-3 py-3">Date</th><th>Type</th><th>Description</th><th className="text-right">Debit</th><th className="text-right">Credit</th><th className="px-3 text-right">Balance</th></tr></thead><tbody className="divide-y divide-white/5">{rows.map(r => <tr key={r.id}><td className="px-3 py-3 text-slate-400">{new Date(r.date).toLocaleDateString("id-ID")}</td><td className="text-slate-500">{r.movementType}</td><td className="text-slate-300">{r.description}</td><td className="text-right text-red-300">{Number(r.debit) ? money(r.debit, currency) : "—"}</td><td className="text-right text-emerald-300">{Number(r.credit) ? money(r.credit, currency) : "—"}</td><td className="px-3 text-right font-semibold text-white">{money(r.balance, currency)}</td></tr>)}</tbody></table></div>;
}

export default function InvestmentDashboardV4() {
  const [data, setData] = useState<Overview | null>(null);
  const [screen, setScreen] = useState<"overview" | "transactions" | "accounts">("overview");
  const [accountId, setAccountId] = useState("");
  const [ledger, setLedger] = useState<Ledger | null>(null);
  const [selectedAssetId, setSelectedAssetId] = useState("");
  const [historyRows, setHistoryRows] = useState<RdnHistoryRow[]>([]);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [editing, setEditing] = useState<Account | null>(null);
  const [showTrade, setShowTrade] = useState(false);
  const [showSellAll, setShowSellAll] = useState(false);
  const [sellAllAssetId, setSellAllAssetId] = useState("");
  const [sellAllPrice, setSellAllPrice] = useState("");
  const [showBalanceEditor, setShowBalanceEditor] = useState(false);
  const [balanceValue, setBalanceValue] = useState("");
  const [withdrawWalletId, setWithdrawWalletId] = useState("");
  const [withdrawAmount, setWithdrawAmount] = useState("");
  const [wallets, setWallets] = useState<Array<{ id: string; name: string; balance: string | number; currency: Currency }>>([]);
  const [accountForm, setAccountForm] = useState<AccountForm>({ providerName: "", websiteUrl: "", rdnBankName: "", rdnAccountNumber: "", buyFeePct: "", sellFeePct: "", currencyId: "" });
  const [trade, setTrade] = useState<Trade>({ type: "BUY", assetId: "", assetQuery: "", quantity: "", unitPrice: "", tax: "0", other: "0", date: today(), sourceLotId: "", fundingCashAccountId: "" });

  const reload = async () => setData(await getOverview());
  const loadLedger = async (id: string) => { const r = await fetch(`/api/investments/v2?accountId=${encodeURIComponent(id)}`, { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load account transactions."); setLedger(j); };
  const loadHistory = async (cashId: string) => { if (!cashId) { setHistoryRows([]); return; } setHistoryLoading(true); try { const r = await fetch(`/api/investments/cash-transfer?cashAccountId=${encodeURIComponent(cashId)}`, { cache: "no-store" }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Unable to load RDN history."); setHistoryRows(j.rows ?? []); } finally { setHistoryLoading(false); } };
  const loadWallets = async () => { const r = await fetch("/api/investments/cash-transfer", { cache: "no-store" }); const j = await r.json(); if (r.ok) setWallets(j.wallets ?? []); };

  useEffect(() => { reload().catch(e => setMessage(e instanceof Error ? e.message : "Unable to load investments.")); loadWallets().catch(() => undefined); }, []);
  useEffect(() => { if (accountId) { loadLedger(accountId).catch(e => setMessage(e instanceof Error ? e.message : "Unable to load account transactions.")); const cashId = data?.accounts.find(a => a.id === accountId)?.cashAccount?.id || ""; loadHistory(cashId).catch(e => setMessage(e instanceof Error ? e.message : "Unable to load RDN history.")); } }, [accountId]);

  const accounts = data?.accounts ?? [];
  const currencies = data?.currencies ?? [];
  const assets = data?.assets ?? [];
  const holdings = data?.holdings ?? [];
  const cashAccounts = data?.cashAccounts ?? [];
  const selected = accounts.find(a => a.id === accountId);
  const selectedCash = cashAccounts.find(c => c.id === selected?.cashAccount?.id);
  const accountAssets = useMemo(() => { const seen = new Set<string>(); const out: Asset[] = []; for (const row of ledger?.rows ?? []) if (!seen.has(row.asset.id)) { seen.add(row.asset.id); out.push(row.asset); } for (const h of holdings.filter(h => h.account.id === accountId)) if (!seen.has(h.asset.id)) { seen.add(h.asset.id); out.push(h.asset); } return [...out, ...assets.filter(a => !seen.has(a.id))].filter((a, i, arr) => arr.findIndex(x => x.id === a.id) === i); }, [ledger, holdings, assets, accountId]);
  const assetSummaries = useMemo<AssetSummary[]>(() => { if (!ledger || !selected) return []; const sellFeePct = feeInfo(selected).sellFeePct; const groups = new Map<string, LotRow[]>(); for (const row of ledger.rows) { if (Number(row.remainingQuantity) <= 0) continue; const list = groups.get(row.asset.id) ?? []; list.push(row); groups.set(row.asset.id, list); } return [...groups.values()].map(rows => { const asset = rows[0].asset; const qty = rows.reduce((s, r) => s + Number(r.remainingQuantity), 0); const cost = rows.reduce((s, r) => s + Number(r.totalCost) * (Number(r.remainingQuantity) / Math.max(Number(r.quantity), 1)), 0); const avgCost = qty ? cost / qty : 0; const currentPrice = rows.find(r => r.currentPrice != null)?.currentPrice == null ? null : Number(rows.find(r => r.currentPrice != null)?.currentPrice); const marketValue = currentPrice == null ? 0 : qty * currentPrice; const sellFee = marketValue * sellFeePct / 100; const netValue = marketValue - sellFee; const pnl = netValue - cost; const minSell = qty && sellFeePct < 100 ? (cost / qty) / (1 - sellFeePct / 100) : 0; return { asset, quantity: qty, cost, avgCost, currentPrice, marketValue, sellFee, netValue, pnl, minSell, rows }; }).sort((a, b) => b.marketValue - a.marketValue); }, [ledger, selected]);
  const selectedSummary = assetSummaries.find(a => a.asset.id === selectedAssetId) ?? assetSummaries[0];
  const detailRows = useMemo(() => { const rows = ledger?.rows ?? []; return rows.filter(r => !selectedAssetId || r.asset.id === selectedAssetId); }, [ledger, selectedAssetId]);
  const openDetails = detailRows.filter(r => Number(r.remainingQuantity) > 0).sort((a, b) => new Date(b.transactionDate).getTime() - new Date(a.transactionDate).getTime());
  const closedDetails = detailRows.flatMap(r => r.sales.map(s => ({ lot: r, sale: s }))).sort((a, b) => new Date(b.sale.date).getTime() - new Date(a.sale.date).getTime());
  const sellAllAsset = assetSummaries.find(a => a.asset.id === sellAllAssetId);
  const sellAllPreview = sellAllAsset && sellAllPrice ? (() => { const p = Number(sellAllPrice); const feePct = feeInfo(selected!).sellFeePct; const rows = sellAllAsset.rows.map(row => { const qty = Number(row.remainingQuantity); const gross = qty * p; const sf = gross * feePct / 100; const cost = Number(row.totalCost) * (qty / Math.max(Number(row.quantity), 1)); const net = gross - sf; return { row, qty, gross, sellFee: sf, net, cost, pnl: net - cost }; }); return { rows, totalGross: rows.reduce((s, x) => s + x.gross, 0), totalFee: rows.reduce((s, x) => s + x.sellFee, 0), totalNet: rows.reduce((s, x) => s + x.net, 0), totalCost: rows.reduce((s, x) => s + x.cost, 0), pnl: rows.reduce((s, x) => s + x.pnl, 0) }; })() : null;

  const run = async (body: Record<string, unknown>, success: string, route: "v2" | "v4" = "v2") => { setBusy(true); setMessage(""); try { if (route === "v4") await postV4(body); else await postV2(body); await reload(); if (accountId) { await loadLedger(accountId); const cashId = accounts.find(a => a.id === accountId)?.cashAccount?.id || ""; await loadHistory(cashId); } setMessage(success); return true; } catch (e) { setMessage(e instanceof Error ? e.message : "Operation failed."); return false; } finally { setBusy(false); } };

  const selectAccount = (id: string, destination: "accounts" | "transactions" = "accounts") => { setAccountId(id); setScreen(destination); setSelectedAssetId(""); const a = accounts.find(x => x.id === id); setTrade(t => ({ ...t, assetId: "", assetQuery: "", sourceLotId: "", fundingCashAccountId: a?.cashAccount?.id || "" })); };
  const openAccountEditor = (account?: Account) => { setEditing(account ?? null); if (account) { const f = feeInfo(account); setAccountForm({ providerName: account.provider.name, websiteUrl: account.provider.websiteUrl || "", rdnBankName: f.rdnBankName, rdnAccountNumber: f.rdnAccountNumber, buyFeePct: String(f.buyFeePct), sellFeePct: String(f.sellFeePct), currencyId: account.currency.id }); } else setAccountForm({ providerName: "", websiteUrl: "", rdnBankName: "", rdnAccountNumber: "", buyFeePct: "", sellFeePct: "", currencyId: currencies[0]?.id || "" }); setShowAccountModal(true); };
  const openTrade = (type: "BUY" | "SELL", row?: LotRow) => { setTrade({ type, assetId: row?.asset.id ?? selectedSummary?.asset.id ?? "", assetQuery: row ? assetLabel(row.asset) : selectedSummary ? assetLabel(selectedSummary.asset) : "", quantity: "", unitPrice: row?.currentPrice ? String(row.currentPrice) : selectedSummary?.currentPrice ? String(selectedSummary.currentPrice) : "", tax: "0", other: "0", date: today(), sourceLotId: row?.lotId ?? "", fundingCashAccountId: selected?.cashAccount?.id || "" }); setShowTrade(true); };

  async function saveAccount(e: FormEvent) { e.preventDefault(); const payload = { ...accountForm, buyFeePct: Number(accountForm.buyFeePct || 0), sellFeePct: Number(accountForm.sellFeePct || 0) }; const ok = await run(editing ? { action: "account.update", accountId: editing.id, ...payload } : { action: "account.create", ...payload }, editing ? "Account updated." : "Account created.", "v4"); if (ok) setShowAccountModal(false); }
  async function deleteAccount(account: Account) { if (!window.confirm(`Hapus ${account.provider.name}? Account hanya dapat dihapus jika belum memiliki history/holding/saldo.`)) return; await run({ action: "account.delete", accountId: account.id }, "Account deleted.", "v4"); if (accountId === account.id) { setAccountId(""); setLedger(null); setScreen("accounts"); } }
  async function closeAccount(account: Account) { if (!window.confirm(`Tutup ${account.provider.name}?`)) return; const ok = await run({ action: "account.close", accountId: account.id }, "Account closed.", "v4"); if (ok && accountId === account.id) { setAccountId(""); setLedger(null); } }

  async function submitTrade(e: FormEvent) { e.preventDefault(); if (!selected) return; let effectiveAsset = accountAssets.find(a => a.id === trade.assetId) ?? accountAssets.find(a => assetLabel(a).toLowerCase() === trade.assetQuery.trim().toLowerCase()); if (!effectiveAsset && trade.type === "BUY") { const symbol = trade.assetQuery.trim().toUpperCase(); try { effectiveAsset = await postV2({ action: "asset.resolve", accountId: selected.id, symbol, name: symbol, currencyId: selected.currency.id, assetType: "STOCK", unitName: "share" }); } catch (e) { setMessage(e instanceof Error ? e.message : "Unable to create asset."); return; } } if (!effectiveAsset) { setMessage("Pilih asset yang valid."); return; } const units = unitsPerLot(effectiveAsset); const qty = Number(trade.quantity) * units; if (!Number.isFinite(qty) || qty <= 0 || !Number.isFinite(Number(trade.unitPrice)) || Number(trade.unitPrice) <= 0) { setMessage("Quantity dan price harus lebih besar dari nol."); return; } if (!trade.fundingCashAccountId) { setMessage("Pilih RDN settlement."); return; } if (trade.type === "SELL") { const row = ledger?.rows.find(r => r.lotId === trade.sourceLotId); if (!row || row.asset.id !== effectiveAsset.id || qty > Number(row.remainingQuantity)) { setMessage("Quantity melebihi remaining lot."); return; } } const feePct = trade.type === "BUY" ? feeInfo(selected).buyFeePct : feeInfo(selected).sellFeePct; const gross = qty * Number(trade.unitPrice); const ok = await run({ action: "transaction.create", accountId: selected.id, assetId: effectiveAsset.id, transactionType: trade.type, transactionDate: new Date(trade.date).toISOString(), quantity: qty, unitPrice: Number(trade.unitPrice), feeAmount: gross * feePct / 100, taxAmount: Number(trade.tax || 0), otherCharges: Number(trade.other || 0), fundingCashAccountId: trade.fundingCashAccountId, sourceLotId: trade.sourceLotId || undefined }, "Transaction saved."); if (ok) { setShowTrade(false); setSelectedAssetId(effectiveAsset.id); } }
  async function updateBalance(e: FormEvent) { e.preventDefault(); if (!selected?.cashAccount?.id) return; const ok = await run({ action: "cash.setBalance", cashAccountId: selected.cashAccount.id, balance: Number(balanceValue), date: new Date(today()).toISOString() }, "RDN balance updated."); if (ok) setShowBalanceEditor(false); }
  async function withdraw() { const amount = Number(withdrawAmount); if (!selectedCash?.id || !withdrawWalletId || !amount || amount <= 0) return; setBusy(true); setMessage(""); try { const r = await fetch("/api/investments/cash-transfer", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ direction: "WITHDRAW", cashAccountId: selectedCash.id, walletId: withdrawWalletId, amount, date: new Date().toISOString() }) }); const j = await r.json(); if (!r.ok || j.error) throw new Error(j.error || "Withdrawal failed."); await reload(); await loadLedger(accountId); await loadHistory(selectedCash.id); setWithdrawAmount(""); setMessage("Dana berhasil dipindahkan ke Wallet."); } catch (e) { setMessage(e instanceof Error ? e.message : "Withdrawal failed."); } finally { setBusy(false); } }
  async function sellAll() { if (!selected || !sellAllAsset || !sellAllPrice || !selected.cashAccount?.id) return; const ok = await run({ action: "transaction.sellAll", accountId: selected.id, assetId: sellAllAsset.asset.id, transactionDate: new Date(today()).toISOString(), unitPrice: Number(sellAllPrice), fundingCashAccountId: selected.cashAccount.id }, "Sell All completed.", "v4"); if (ok) { setShowSellAll(false); setSellAllPrice(""); setSellAllAssetId(""); setSelectedAssetId(sellAllAsset.asset.id); } }

  if (!data) return <div className="mx-auto w-full max-w-[1450px] px-5 py-8 text-sm text-slate-400">Loading Investments…</div>;

  return <div className="mx-auto w-full min-w-0 max-w-[1450px] px-5 py-8 lg:px-8">
    <header className="mb-6 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-[10px] font-semibold uppercase tracking-[.18em] text-emerald-400">Portfolio</p><h1 className="mt-1 text-3xl font-bold text-white">Investments</h1><p className="mt-2 text-sm text-slate-500">Kelola RDN, portfolio, transaction detail dan P/L dari satu account.</p></div><nav className="flex shrink-0 rounded-xl border border-white/10 bg-[#0b121a] p-1"><button className={`rounded-lg px-4 py-2 text-xs font-bold uppercase ${screen === "overview" ? "bg-white/[.09] text-white" : "text-slate-500"}`} onClick={() => setScreen("overview")}>Overview</button><button className={`rounded-lg px-4 py-2 text-xs font-bold uppercase ${screen === "transactions" ? "bg-white/[.09] text-white" : "text-slate-500"}`} onClick={() => { setScreen("transactions"); if (!accountId && accounts[0]) selectAccount(accounts[0].id, "transactions"); }}>Transactions</button><button className={`rounded-lg px-4 py-2 text-xs font-bold uppercase ${screen === "accounts" ? "bg-white/[.09] text-white" : "text-slate-500"}`} onClick={() => setScreen("accounts")}>Accounts</button></nav></header>
    {message && <div className={`mb-4 rounded-xl border px-4 py-3 text-xs ${/error|failed|insufficient|cannot|must|valid|melebihi|tidak/i.test(message) ? "border-red-400/20 bg-red-400/[.05] text-red-300" : "border-emerald-400/20 bg-emerald-400/[.05] text-emerald-300"}`}>{message}</div>}

    {screen === "overview" && <div className="space-y-5"><div className="grid gap-3 md:grid-cols-4">{[["Total Investment",data.summary.totalInvestmentValue,"portfolio + RDN cash"],["RDN Cash",data.summary.totalCash,"all RDN accounts"],["Portfolio",data.summary.totalValue,"current market value"],["Unrealized P/L",data.summary.unrealized,`${Number(data.summary.returnPct || 0).toFixed(2)}% return`]].map(([l,v,s]) => <div className={card} key={String(l)}><p className="text-[10px] uppercase tracking-widest text-slate-500">{l}</p><p className="mt-2 text-xl font-bold text-white">{money(v as number)}</p><p className="mt-1 text-[10px] text-slate-600">{s}</p></div>)}</div><section className={card}><div className="mb-4 flex items-center justify-between"><div><h2 className="font-semibold text-white">Investment Accounts</h2><p className="text-xs text-slate-600">Pilih account untuk masuk ke detail account.</p></div><button type="button" onClick={() => openAccountEditor()} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-xs font-bold text-[#07110b]">+ Add RDN Account</button></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{accounts.filter(a => a.isActive !== false).map(a => <button key={a.id} type="button" onClick={() => selectAccount(a.id, "accounts")} className="rounded-2xl border border-white/10 bg-white/[.02] p-5 text-left hover:border-emerald-400/30"><div className="flex items-start justify-between"><div><p className="font-semibold text-white">{a.provider.name}</p><p className="mt-1 text-xs text-slate-500">{feeInfo(a).rdnBankName ? `RDN ${feeInfo(a).rdnBankName}` : "Investment account"} · {a.currency.code}</p></div><span className="text-[10px] font-bold uppercase tracking-widest text-emerald-300">Open →</span></div><div className="mt-5 grid grid-cols-2 gap-3 text-xs"><div><p className="text-slate-600">RDN Cash</p><p className="mt-1 font-semibold text-white">{money(a.cashAccount?.balance ?? 0, a.currency.code)}</p></div><div><p className="text-slate-600">Portfolio</p><p className="mt-1 font-semibold text-white">{money(holdings.filter(h => h.account.id === a.id).reduce((s,h) => s + Number(h.marketValue), 0), a.currency.code)}</p></div></div></button>)}</div></section></div>}

    {screen === "accounts" && <div className="space-y-5"><section className={card}><div className="mb-4 flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Investment Accounts</h2><p className="text-xs text-slate-600">Account dibuat sekali dan disimpan. Detail hanya muncul setelah account dipilih.</p></div><button type="button" onClick={() => openAccountEditor()} className="rounded-xl bg-emerald-400 px-4 py-2.5 text-xs font-bold text-[#07110b]">+ Add RDN Account</button></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{accounts.filter(a => a.isActive !== false).map(a => <button type="button" key={a.id} onClick={() => selectAccount(a.id, "accounts")} className={`rounded-2xl border p-5 text-left ${accountId === a.id ? "border-emerald-400/50 bg-emerald-400/[.05]" : "border-white/10 bg-white/[.02] hover:border-emerald-400/30"}`}><div className="flex items-start justify-between"><div><p className="font-semibold text-white">{a.provider.name}</p><p className="mt-1 text-xs text-slate-500">{feeInfo(a).rdnBankName ? `RDN ${feeInfo(a).rdnBankName}` : "Investment account"} · {a.currency.code}</p></div><span className="text-xs text-slate-500">{accountId === a.id ? "Selected" : "Open"}</span></div><div className="mt-4 text-xs text-slate-500">Saldo RDN <span className="float-right font-semibold text-white">{money(a.cashAccount?.balance ?? 0, a.currency.code)}</span></div></button>)}</div></section>{selected && <section className="space-y-5"><div className="grid gap-5 lg:grid-cols-2"><div className={card}><div className="flex items-start justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">RDN Cash</p><h3 className="mt-1 text-xl font-bold text-white">{selected.provider.name}</h3><p className="mt-1 text-xs text-slate-500">{feeInfo(selected).rdnBankName ? `RDN ${feeInfo(selected).rdnBankName}` : "RDN"} · {selected.currency.code}</p></div><div className="text-right"><p className="text-[10px] uppercase tracking-widest text-slate-600">Current balance</p><p className="mt-1 text-xl font-bold text-emerald-300">{money(selectedCash?.balance ?? selected.cashAccount?.balance ?? 0, selected.currency.code)}</p></div></div><div className="mt-5 flex flex-wrap gap-2"><button type="button" onClick={() => { setBalanceValue(String(selectedCash?.balance ?? selected.cashAccount?.balance ?? 0)); setShowBalanceEditor(v => !v); }} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs font-bold text-slate-200">{showBalanceEditor ? "Cancel Update" : "Update Balance"}</button><button type="button" onClick={() => openAccountEditor(selected)} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs font-bold text-slate-200">Edit Account</button><button type="button" onClick={() => closeAccount(selected)} disabled={busy || Number(selectedCash?.balance ?? selected.cashAccount?.balance ?? 0) > 0 || holdings.some(h => h.account.id === selected.id && Number(h.quantity) > 0)} className="rounded-xl border border-white/10 px-4 py-2.5 text-xs font-bold text-slate-400 disabled:opacity-30">Close</button><button type="button" onClick={() => deleteAccount(selected)} className="rounded-xl border border-red-400/20 px-4 py-2.5 text-xs font-bold text-red-300">Delete</button></div>{showBalanceEditor && <form onSubmit={updateBalance} className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto]"><input className={input} type="number" min="0" step="0.01" value={balanceValue} onChange={e => setBalanceValue(e.target.value)} /><button className="rounded-xl bg-emerald-400 px-5 py-2.5 text-xs font-bold text-[#07110b]" disabled={busy}>Save balance</button></form>}</div><div className={card}><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">RDN → Wallet</p><h3 className="mt-1 text-xl font-bold text-white">Withdraw</h3><p className="mt-1 text-xs text-slate-500">Pindahkan dana RDN kembali ke Wallet OKANE.</p></div></div><div className="mt-4 grid gap-3"><select className={select} value={withdrawWalletId} onChange={e => setWithdrawWalletId(e.target.value)}><option value="">Select wallet</option>{wallets.filter(w => w.currency.id === selected.currency.id).map(w => <option key={w.id} value={w.id}>{w.name} · {money(w.balance, w.currency.code)}</option>)}</select><div className="grid grid-cols-[1fr_auto] gap-2"><input className={input} type="number" min="0.01" step="0.01" max={String(selectedCash?.balance ?? selected.cashAccount?.balance ?? 0)} value={withdrawAmount} onChange={e => setWithdrawAmount(e.target.value)} placeholder="Amount" /><button type="button" disabled={busy || !withdrawWalletId || !withdrawAmount || Number(withdrawAmount) > Number(selectedCash?.balance ?? selected.cashAccount?.balance ?? 0)} onClick={withdraw} className="rounded-xl bg-emerald-400 px-5 py-2.5 text-xs font-bold text-[#07110b] disabled:opacity-40">Withdraw</button></div></div></div></div><div className={card}><div className="flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">RDN History</p><h3 className="mt-1 text-xl font-bold text-white">Transaction History</h3><p className="mt-1 text-xs text-slate-500">History khusus {selected.provider.name} · {selected.name}.</p></div><button type="button" onClick={() => loadHistory(selected.cashAccount?.id || "")} className="text-xs font-semibold text-emerald-300">Refresh</button></div><div className="mt-4">{historyLoading ? <div className="p-6 text-center text-xs text-slate-600">Loading…</div> : historyRows.length ? <RdnHistory rows={historyRows} currency={selected.currency.code} /> : <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-slate-600">Belum ada transaksi pada RDN ini.</div>}</div></div></section>}</div>}

    {screen === "transactions" && <div className="space-y-5">{!selected ? <section className={card}><p className="text-sm text-slate-400">Pilih investment account terlebih dahulu dari tab Accounts.</p></section> : <><section className={card}><div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">Account</p><h2 className="mt-1 text-xl font-bold text-white">{selected.provider.name}</h2><p className="mt-1 text-xs text-slate-500">{feeInfo(selected).rdnBankName ? `RDN ${feeInfo(selected).rdnBankName}` : "RDN"} · {selected.currency.code}</p></div><div className="flex gap-2"><select className="rounded-xl border border-white/10 bg-[#080f17] px-3 py-2 text-xs text-slate-300" value={accountId} onChange={e => selectAccount(e.target.value, "transactions")}>{accounts.filter(a => a.isActive !== false).map(a => <option key={a.id} value={a.id}>{a.provider.name} · {feeInfo(a).rdnBankName || "RDN"}</option>)}</select><button type="button" onClick={() => openTrade("BUY")} className="rounded-xl bg-emerald-400 px-4 py-2 text-xs font-bold text-[#07110b]">+ Transaction</button></div></div></section><section className={card}><div className="mb-4"><h2 className="text-lg font-semibold text-white">Asset Summary</h2><p className="text-xs text-slate-600">Klik saham untuk memfilter detail transaksi di bawahnya.</p></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{assetSummaries.length ? assetSummaries.map(a => <button type="button" key={a.asset.id} onClick={() => setSelectedAssetId(a.asset.id)} className={`rounded-2xl border p-4 text-left ${selectedAssetId === a.asset.id ? "border-emerald-400/50 bg-emerald-400/[.05]" : "border-white/10 bg-white/[.02] hover:border-emerald-400/30"}`}><div className="flex items-start justify-between"><div><p className="font-semibold text-white">{a.asset.symbol || a.asset.name}</p><p className="mt-1 text-[10px] text-slate-500">{a.asset.name}</p></div><span className="text-[10px] text-slate-500">{a.asset.assetType}</span></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><p className="text-slate-600">Holding</p><p className="mt-1 font-semibold text-white">{nf(a.quantity / unitsPerLot(a.asset), a.asset.assetType === "STOCK" ? 0 : 2)} {a.asset.assetType === "STOCK" ? "lot" : a.asset.unitName}</p><p className="text-[10px] text-slate-600">{nf(a.quantity, 0)} units</p></div><div><p className="text-slate-600">Avg cost</p><p className="mt-1 font-semibold text-white">{money(a.avgCost, selected.currency.code)}</p><p className="text-[10px] text-slate-600">per unit</p></div></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div><p className="text-slate-600">Current</p><p className="mt-1 font-semibold text-white">{a.currentPrice == null ? "—" : money(a.currentPrice, selected.currency.code)}</p></div><div><p className="text-slate-600">P/L</p><p className={`mt-1 font-semibold ${a.pnl >= 0 ? "text-emerald-300" : "text-red-300"}`}>{money(a.pnl, selected.currency.code)}</p></div></div><div className="mt-4 flex items-center justify-between text-[10px]"><span className="text-slate-600">Break-even sell</span><span className="font-semibold text-amber-300">{money(a.minSell, selected.currency.code)}</span></div><div className="mt-4 flex gap-2"><span className="flex-1 rounded-lg border border-white/10 px-3 py-2 text-center text-[10px] text-slate-400">Details</span><span role="button" tabIndex={0} onClick={e => { e.stopPropagation(); setSellAllAssetId(a.asset.id); setSellAllPrice(a.minSell ? String(a.minSell) : a.currentPrice ? String(a.currentPrice) : ""); setShowSellAll(true); }} className="flex-1 rounded-lg bg-emerald-400 px-3 py-2 text-center text-[10px] font-bold text-[#07110b]">Sell All</span></div></button>) : <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-slate-600">Belum ada open holding pada account ini.</div>}</div></section><section className={card}><div className="mb-5 flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Transaction Detail</h2><p className="text-xs text-slate-600">{selectedAssetId ? `Filtered: ${selectedSummary?.asset.symbol || selectedSummary?.asset.name}` : "Semua asset"}. Open positions selalu ditampilkan paling atas.</p></div>{selectedAssetId && <button type="button" onClick={() => setSelectedAssetId("")} className="text-xs text-slate-500 hover:text-white">Clear filter</button>}</div><div className="space-y-4"><div className="rounded-2xl border border-emerald-400/10 bg-emerald-400/[.02] p-4"><div className="mb-3 flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-emerald-400">Open positions</p><p className="mt-1 text-xs text-slate-600">Lot yang masih belum sepenuhnya terjual.</p></div><span className="rounded-full border border-emerald-400/20 px-2 py-1 text-[10px] text-emerald-300">{openDetails.length} lot</span></div>{openDetails.length ? <div className="space-y-2">{openDetails.map(row => <div key={row.id} className="grid gap-3 rounded-xl border border-white/10 bg-[#080f17] p-4 lg:grid-cols-[1.2fr_.8fr_.9fr_.9fr_auto]"><div><p className="font-semibold text-white">{row.asset.symbol || row.asset.name}</p><p className="text-[10px] text-slate-500">BUY · {new Date(row.transactionDate).toLocaleDateString("id-ID")}</p></div><div><p className="text-[10px] text-slate-600">Remaining</p><p className="mt-1 font-semibold text-white">{nf(Number(row.remainingQuantity) / unitsPerLot(row.asset), row.asset.assetType === "STOCK" ? 0 : 2)} {row.asset.assetType === "STOCK" ? "lot" : row.asset.unitName}</p></div><div><p className="text-[10px] text-slate-600">Purchase cost</p><p className="mt-1 font-semibold text-white">{money(row.totalCost, selected.currency.code)}</p></div><div><p className="text-[10px] text-slate-600">Min sell</p><p className="mt-1 font-semibold text-amber-300">{money(row.minimumSellPrice, selected.currency.code)}</p></div><button type="button" onClick={() => openTrade("SELL", row)} className="rounded-xl bg-emerald-400 px-4 py-2 text-xs font-bold text-[#07110b]">Sell</button></div>)}</div> : <div className="rounded-xl border border-dashed border-white/10 p-6 text-center text-xs text-slate-600">Tidak ada open position untuk filter ini.</div>}</div><div className="rounded-2xl border border-white/10 p-4"><div className="mb-3 flex items-center justify-between"><div><p className="text-[10px] uppercase tracking-widest text-slate-500">Closed transactions</p><p className="mt-1 text-xs text-slate-600">Detail penjualan yang sudah menyelesaikan lot.</p></div><span className="rounded-full border border-white/10 px-2 py-1 text-[10px] text-slate-500">{closedDetails.length} sale</span></div>{closedDetails.length ? <div className="overflow-x-auto"><table className="w-full min-w-[860px] text-left text-xs"><thead className="border-b border-white/5 text-[10px] uppercase tracking-wider text-slate-600"><tr><th className="px-3 py-3">Asset</th><th>Buy date</th><th>Sell date</th><th>Qty</th><th>Sell price</th><th>Net proceeds</th><th className="text-right">Realized P/L</th></tr></thead><tbody className="divide-y divide-white/5">{closedDetails.map(x => <tr key={`${x.lot.id}-${x.sale.id}`}><td className="px-3 py-3 font-semibold text-white">{x.lot.asset.symbol || x.lot.asset.name}</td><td className="text-slate-500">{new Date(x.lot.transactionDate).toLocaleDateString("id-ID")}</td><td className="text-slate-500">{new Date(x.sale.date).toLocaleDateString("id-ID")}</td><td>{nf(Number(x.sale.quantity) / unitsPerLot(x.lot.asset), x.lot.asset.assetType === "STOCK" ? 0 : 2)}</td><td>{money(x.sale.price, selected.currency.code)}</td><td>{money(x.sale.proceeds, selected.currency.code)}</td><td className={`text-right ${Number(x.sale.realized) >= 0 ? "text-emerald-300" : "text-red-300"}`}>{money(x.sale.realized, selected.currency.code)}</td></tr>)}</tbody></table></div> : <div className="rounded-xl border border-dashed border-white/10 p-6 text-center text-xs text-slate-600">Belum ada closed transaction untuk filter ini.</div>}</div></div></section></>}</div>}

    <AccountModal open={showAccountModal} editing={editing} form={accountForm} currencies={currencies} onClose={() => setShowAccountModal(false)} onChange={setAccountForm} onSubmit={saveAccount} busy={busy} />
    {selected && <TradeModal open={showTrade} trade={trade} assets={accountAssets} account={selected} ledger={ledger} compatibleCashId={selected.cashAccount?.id || ""} onClose={() => setShowTrade(false)} onChange={setTrade} onSubmit={submitTrade} busy={busy} />}
    <SellAllModal open={showSellAll} asset={sellAllAsset} preview={sellAllPreview} price={sellAllPrice} currency={selected?.currency.code || "IDR"} onClose={() => setShowSellAll(false)} onPrice={setSellAllPrice} onConfirm={sellAll} busy={busy} />
  </div>;
}
